  display: flex;
  flex-direction: column;
  align-items: stretch;
  width: 100%;
  min-height: 48px;
  box-sizing: border-box;
  border: none;
  border-radius: 8px;
  padding: 4px 8px;
  background: transparent;
  cursor: pointer;
  text-align: left;
  color: var(--dsw-alias-label-primary);
}

.searchResultRow:hover {
  background: var(--dsw-alias-interactive-bg-hover);
}

.searchResultRow.selected {
  background: var(--dsw-alias-interactive-bg-hover);
}

.searchResultHeading {
  display: flex;
  align-items: center;
  min-width: 0;
}

.searchResultTitle {
  min-width: 0;
  margin-left: 4px;
  overflow: hidden;
  text-overflow: ellipsis;
