            isTyped: error instanceof HelperCallError,
            name: error.name,
            helperName: error.helperName,
            message: error.message,
          };
        }
      `,
      bindings: [{
        global: 'helpers',
        functions: { fail: async () => { throw new Error('nope') } },
        errorClass: { name: 'HelperCallError', memberNameProperty: 'helperName' },
